INSERT INTO `accidents` VALUES ('01/ACC/BRA/DURI/2026','CS-41001','2026-05-14','2026-05-11 07:30:00',NULL,'M. Fajar DC',NULL,'Pada tanggal 11 Mei 2026 pukul 14.30 WIB, unit sedang melakukan pengisian material powder binder/cement di area pengisian. Terjadi Error System Penaburan cement yang disebabkan pada saat pengisian cement operator tidak menyalakan tombol pada monitor sehingga sistem error dan cement tidak dapat ditabur.',NULL,NULL,NULL,'Moderate',NULL,0.00,0,0.00,NULL,NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,'{\"docNo\": \"01/ACC/BRA/DURI/2026\", \"tarNo\": \"01/TAR/05/2026\", \"impact\": {\"physicalDamage\": \"Error System Penaburan & Valve Blockage\", \"productionImpact\": \"Penaburan Semen Terhenti (Delay Stabilisasi)\", \"estimatedRepairCost\": 15500000, \"totalFinancialImpact\": 28000000, \"estimatedDowntimeDays\": 3}, \"status\": \"CAPA_Pending\", \"location\": \"Site RWI Duri (Project Zona 4)\", \"severity\": \"Moderate\", \"unitCode\": \"CS-41001\", \"unitName\": \"Powder Binder Spreader XCMG XKC185\", \"makeModel\": \"XCMG XKC185\", \"chronology\": \"Pada tanggal 11 Mei 2026 pukul 14.30 WIB, unit sedang melakukan pengisian material powder binder/cement di area pengisian. Terjadi Error System Penaburan cement yang disebabkan pada saat pengisian cement operator tidak menyalakan tombol pada monitor sehingga sistem error dan cement tidak dapat ditabur.\", \"reportDate\": \"2026-05-14\", \"environment\": {\"cargo\": \"Overload Pengisian Cement\", \"density\": \"Padat Operasional\", \"weather\": \"Cerah\", \"lighting\": \"Siang Hari (Terang)\", \"roadCondition\": \"Kering / Rata\"}, \"causeFactors\": [\"Human factor\", \"Procedural / System failure\"], \"incidentDate\": \"2026-05-11 14:30\", \"isUnitLocked\": true, \"licensePlate\": \"BM 9012 RWI\", \"operatorName\": \"M. Fajar DC\", \"operatorTenure\": \"< 1 bulan (Unit Baru)\", \"causeExplanation\": \"Operator tidak mengikuti urutan tombol pengisian monitor saat mengisi material cement, serta belum ada interlock otomatis.\", \"correctiveAction\": \"Unit dihentikan operasional (ACCIDENT_HOLD). Sebagian cement dibongkar dan diisi ulang oleh teknisi XCMG.\", \"preventiveAction\": \"Refresher training operator penabur semen, update SOP serah terima unit baru, dan penambahan label urutan instruksi di kabin.\"}','Reported'),('02/ACC/BRA/YARD/2026','DT-00052','2026-06-20','2026-06-19 09:15:00',NULL,'Suwardi (Welder/Mekanik)',NULL,'Saat bermanuver mundur di area bay workshop, engsel pintu Ombeng tersangkut pada tiang penyangga sehingga engsel patah, kunci pintu bengkok, dan pelat lantai robek.',NULL,NULL,NULL,'Minor',NULL,0.00,0,0.00,NULL,NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,'{\"docNo\": \"02/ACC/BRA/YARD/2026\", \"tarNo\": \"\", \"impact\": {\"physicalDamage\": \"Pintu ombeng belakang rusak, pelat sobek 30cm, engsel patah 2 titik.\", \"productionImpact\": \"Keterlambatan mobilisasi unit ke tambang.\", \"estimatedRepairCost\": 4500000, \"totalFinancialImpact\": 5500000, \"estimatedDowntimeDays\": 1}, \"status\": \"Investigating\", \"location\": \"Yard KM 12 Area Workshop\", \"severity\": \"Minor\", \"unitCode\": \"DT-00052\", \"unitName\": \"Dump Truck Hino Ranger FM 280 JD\", \"makeModel\": \"Hino Ranger FM 280 JD\", \"chronology\": \"Saat bermanuver mundur di area bay workshop, engsel pintu Ombeng tersangkut pada tiang penyangga sehingga engsel patah, kunci pintu bengkok, dan pelat lantai robek.\", \"reportDate\": \"2026-06-20\", \"environment\": {\"cargo\": \"Kosong (Unloaded)\", \"density\": \"Sepi\", \"weather\": \"Hujan Gerimis\", \"lighting\": \"Sore Hari (Redup)\", \"roadCondition\": \"Licin/Berlumpur\"}, \"causeFactors\": [\"Human factor\", \"Environmental conditions\"], \"incidentDate\": \"2026-06-19 16:15\", \"isUnitLocked\": true, \"licensePlate\": \"B 9642 KYW\", \"operatorName\": \"Suwardi (Welder/Mekanik)\", \"operatorTenure\": \"2 Tahun\", \"causeExplanation\": \"Kurangnya observasi pandangan belakang akibat kaca spion kotor dan kondisi redup.\", \"correctiveAction\": \"Perbaikan pintu ombeng (fabrikasi dan welding lokal). Unit ditahan sementara (ACCIDENT_HOLD).\", \"preventiveAction\": \"Pemasangan rubber stopper di area tiang penyangga, wajib ada spotter/pemandu saat unit mundur di area workshop sempit.\"}','Reported');
