INSERT INTO `roles` VALUES (1,'Administrator','Full access to system configuration, users, and DB management'),(2,'Equipment Manager','Head of Equipment - Access to executive dashboard & WO approvals'),(3,'Maintenance Planner','Responsible for PM scheduling, WO creation, & parts kitting'),(4,'Mekanik Senior','Responsible for executing WO repair & timesheet logs'),(5,'Mekanik Junior / Helper','Assisting senior mechanics on daily repair jobs'),(6,'Welder / Fabrikator','Responsible for welding, body protection, & ombeng locks'),(7,'Inspector K3L / Safety','Responsible for P2H inspections & HSE accident reports'),(8,'Logistic Head','Responsible for spare parts inventory & SPB approvals'),(9,'HRD Manager','Responsible for personnel timesheet & SPL authorization'),(10,'Asset Manager','Responsible for asset valuation, mutation BAST, & release approval');
