INSERT INTO `system_notifications` VALUES (1,'Inspeksi P2H','M. Fajar DC','Operator','P2H_REJECT','Inspeksi P2H Ditolak - CS-41001 (BREAKDOWN)','Operator M. Fajar DC menyerahkan Form P2H #1042 untuk Powder Binder Spreader CS-41001 dengan temuan 3 item kritikal (Error System Penaburan & Valve Blockage). Status unit otomatis dialihkan ke BREAKDOWN dan tiket WO darurat #WO-26-102 diterbitkan.','[\"M. Fajar DC (Operator)\", \"Rahmad K (Mekanik)\", \"Teknisi XCMG\", \"Budi Nugraha (Supervisor)\"]','{\"tables\": [\"p2h_inspections\", \"assets\", \"work_orders\"], \"records\": [{\"id\": \"1042\", \"table\": \"p2h_inspections\"}, {\"id\": \"CS-41001\", \"table\": \"assets\"}, {\"id\": \"WO-26-102\", \"table\": \"work_orders\"}]}',0,'2026-08-09 07:15:00'),(2,'Work Order Kanban','Agus Sudradjat','Planner','WO_DISPATCH','Disposisi Work Order #WO-26-101 (DT-00049)','Planner Agus Sudradjat mengalihkan status WO-26-101 dari OPEN menjadi IN_PROGRESS untuk perbaikan Kopling & Transmisi Dump Truck DT-00049 di Bay 2 Workshop Duri.','[\"Agus Sudradjat (Planner)\", \"Suwardi (Welder/Mekanik)\", \"Rahmad K (Mekanik Lead)\"]','{\"tables\": [\"work_orders\", \"work_order_logs\", \"assets\"], \"records\": [{\"id\": \"WO-26-101\", \"table\": \"work_orders\"}, {\"id\": \"DT-00049\", \"table\": \"assets\"}]}',0,'2026-08-09 06:40:00'),(3,'Condition Monitoring','Bambang Irawan','Inspector','CM_CUTTING_LOG','Peringatan Konsumabel Cutting Bit Over Limit - PM-41001','Inspector Bambang Irawan memasukkan kontrol shift Cutting Bit untuk unit Cold Milling PM-41001. Terdeteksi 2 pcs bit hilang dan rasio 3.4 bit/HM (di atas limit 3.0 bit/HM).','[\"Bambang Irawan (Inspector)\", \"Joko W (Supervisor Logistik)\", \"Brian Nugraha (Head of Equipment)\"]','{\"tables\": [\"condition_monitoring_logs\", \"consumable_items\"], \"records\": [{\"id\": \"CM-CUT-20260809-01\", \"table\": \"condition_monitoring_logs\"}]}',0,'2026-08-09 05:20:00'),(4,'Fleet Standby Audit','Kanz Dzakipr','Auditor','STANDBY_AUDIT','Pembaruan Audit Lapangan 48 Unit Standby','Auditor Kanz Dzakipr merekonsiliasi lokasi unit standby: 35 Unit di Yard Duri (Dump Truck) dan 13 Unit di Yard Prabumulih (Excavator). Berkas rekomendasi redeployment diterbitkan.','[\"Kanz Dzakipr (Auditor)\", \"Brian Nugraha (Head of Equipment)\", \"Site Manager Duri\"]','{\"tables\": [\"assets\", \"asset_locations\", \"standby_audits\"], \"records\": [{\"id\": \"AUD-2026-08\", \"table\": \"standby_audits\"}]}',1,'2026-08-09 03:05:00'),(5,'PM Forecast Tracker','Heri Setiawan','Maintenance Planner','PM_FORECAST','Penjadwalan Ulang PM 500 HM - EXC-00007','Maintenance Planner Heri Setiawan memperbarui jadwal service berkala 500 HM untuk Excavator Komatsu EXC-00007 setelah verifikasi SMR Telematika KOMTRAX.','[\"Heri Setiawan (Planner)\", \"Tim Mekanik Yard Duri\"]','{\"tables\": [\"pm_schedules\", \"telematics_komtrax\"], \"records\": [{\"id\": \"PM-EXC-00007-500\", \"table\": \"pm_schedules\"}]}',1,'2026-08-09 01:30:00');
