--
-- Table structure for table `work_orders`
--

DROP TABLE IF EXISTS `work_orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `work_orders` (
  `wo_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `asset_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `hull_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `equipment_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `current_hm_km` decimal(12,2) DEFAULT NULL,
  `trouble_at` datetime DEFAULT NULL,
  `location_id` int DEFAULT NULL,
  `raw_location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `issue_description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `downtime_formatted` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `downtime_minutes` int DEFAULT '0',
  `is_downtime` tinyint(1) DEFAULT '1',
  `is_forced_operation` tinyint(1) NOT NULL DEFAULT '0',
  `mitigation_action` text COLLATE utf8mb4_unicode_ci,
  `status` enum('Open','In Progress','Waiting Part','Testing','Closed','Cancelled') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Open',
  `priority` enum('Normal','High','Emergency') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Normal',
  `maintenance_type` enum('Corrective','Preventive','Inspection','Emergency') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Corrective',
  `parts_requirement` enum('UNASSESSED','REQUIRED','NOT_REQUIRED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UNASSESSED',
  `parts_requirement_note` text COLLATE utf8mb4_unicode_ci,
  `assigned_mechanic` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Belum ada PIC',
  `assigned_mechanics_json` text COLLATE utf8mb4_unicode_ci,
  `root_cause` text COLLATE utf8mb4_unicode_ci,
  `repair_action` text COLLATE utf8mb4_unicode_ci,
  `reported_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `repair_started_at` timestamp NULL DEFAULT NULL,
  `estimated_completion_at` datetime DEFAULT NULL,
  `closed_at` timestamp NULL DEFAULT NULL,
  `verification_supervisor_id` int DEFAULT NULL,
  `before_photo_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `after_photo_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`wo_id`),
  KEY `asset_id` (`asset_id`),
  KEY `location_id` (`location_id`),
  KEY `verification_supervisor_id` (`verification_supervisor_id`),
  KEY `idx_wo_status` (`status`),
  KEY `idx_wo_priority` (`priority`),
  KEY `idx_wo_trouble_at` (`trouble_at`),
  KEY `idx_wo_forced_operation` (`is_forced_operation`,`status`),
  CONSTRAINT `work_orders_ibfk_1` FOREIGN KEY (`asset_id`) REFERENCES `assets` (`asset_id`) ON DELETE CASCADE,
  CONSTRAINT `work_orders_ibfk_2` FOREIGN KEY (`location_id`) REFERENCES `locations` (`location_id`) ON DELETE SET NULL,
  CONSTRAINT `work_orders_ibfk_3` FOREIGN KEY (`verification_supervisor_id`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

