INSERT INTO `work_orders` VALUES ('WO-26-001','DZ-00002',NULL,NULL,NULL,NULL,NULL,'Yard KM 12 Duri','STUCK ENGINE. Mati total, Over heat, minyak di Nozzle sudah bercampur air, packing - head bocor','579 jam 16 menit',34756,1,0,NULL,'Closed','Normal','Corrective','UNASSESSED',NULL,'Belum ada PIC',NULL,NULL,NULL,'2026-08-04 23:42:24',NULL,NULL,NULL,NULL,NULL,NULL),('WO-26-002','DT-00049',NULL,NULL,NULL,NULL,NULL,'Yard KM 12 Duri','MEKANIKAL & K3 - 1. Perbaikan lampu hazard. - 2. Karet ting tong bawah kanan 1 Pcs, - 3. Karet ting tong atas 2 Pcs, - 4. Karet susu/bantalan 4 Pcs - 5. Seal cylinder hoist bocor - 6. Housekeeping - 7. Perbaikan kepala Baterai - 8. Mounting gantungan knalpot - WELDING - 1. Lantai dump - 2. Sub Chasis retak kiri & kanan luar dalam - 3. Tutup aki - 4. Dinding dump kanan bocor. - 5. Underrun retak dan bengkok - 6. Gantungan Ban Serep','371 jam 51 menit',22311,1,0,NULL,'Closed','Normal','Corrective','UNASSESSED',NULL,'Belum ada PIC',NULL,NULL,NULL,'2026-08-04 23:42:24',NULL,NULL,NULL,NULL,NULL,NULL),('WO-26-003','DT-04024',NULL,NULL,NULL,NULL,NULL,'Borrow Pit Harapan Baru','Radiator Bocor, Mounting Engine','49 jam 40 menit',2980,1,0,NULL,'Closed','Normal','Corrective','UNASSESSED',NULL,'Belum ada PIC',NULL,NULL,NULL,'2026-08-04 23:42:24',NULL,NULL,NULL,NULL,NULL,NULL),('WO-26-004','DT-00055',NULL,NULL,NULL,NULL,NULL,'Yard KM 12 Duri','1. Karet ting tong bawah kanan 2 Pcs, - 2. Karet ting tong atas 4 Pcs, - 3. Karet susu/bantalan 4 Pcs - 4. Lantai dump - 5. Sub Chasis retak kiri & kanan luar dalam - 6. Seal cylinder hoist bocor - 7. Tutup aki - 8. Dinding dump kanan bocor. - 9. Underrun retak dan bengkok - 10. Gantungan Ban Serep - 11. Housekeeping - 12. Perbaikan kepala Baterai - 13. Pemasangan per depan - REGREASING','368 jam 00 menit',22080,1,0,NULL,'Closed','Normal','Corrective','UNASSESSED',NULL,'Belum ada PIC',NULL,NULL,NULL,'2026-08-04 23:42:24',NULL,NULL,NULL,NULL,NULL,NULL),('WO-26-005','DT-00059',NULL,NULL,NULL,NULL,NULL,'Yard KM 12 Duri','WELDING - 1. Cover body kiri penyok - 2. Kisi2 chasis dump - 3. Bracket knalpot - 4. Baut clamp sub chasis. Cover body - 5. Kunci Om Beng - MEKANIKAL & K3 - 1. Pls check body set / trunion. - 2. Tutup Baterai - 3. Ting tong atas bawah - 4. Karet susu OK - 5. Apar low pressure - 6. Lock safety belt kiri - 7. Clemp per depan kanan - 8. Grease all fitting - 9. Housekeeping - 10. Simpang 4 PTO - 11. Safety lumpur kanan depan - 12. URL Belakang - Temuan baru : pelek roda retak 2 Pcs . - Regreasing','202 jam 21 menit',12141,1,0,NULL,'Closed','Normal','Corrective','UNASSESSED',NULL,'Belum ada PIC',NULL,NULL,NULL,'2026-08-04 23:42:24',NULL,NULL,NULL,NULL,NULL,NULL),('WO-26-006','DT-00046',NULL,NULL,NULL,NULL,NULL,'Borrow Pit Harapan Baru','1. Ting tong atas bawah - Inspek tgl 18-12-2025 - 2. Alarm mundur - 3. Grease all fitting','262 jam 40 menit',15760,1,0,NULL,'Closed','Normal','Corrective','UNASSESSED',NULL,'Belum ada PIC',NULL,NULL,NULL,'2026-08-04 23:42:24',NULL,NULL,NULL,NULL,NULL,NULL),('WO-26-007','DT-00074',NULL,NULL,NULL,NULL,NULL,'Borrow Pit Harapan Baru','1. Om Beng bengkok / retak kiri, Tidak bisa dikunci - 2. Bracket tutup Baterai. - 3. Stabil front - 4. Grease all fitting','89 jam 57 menit',5397,1,0,NULL,'Closed','Normal','Corrective','UNASSESSED',NULL,'Belum ada PIC',NULL,NULL,NULL,'2026-08-04 23:42:24',NULL,NULL,NULL,NULL,NULL,NULL),('WO-26-008','DT-00060',NULL,NULL,NULL,NULL,NULL,'Yard KM 12 Duri','WELDING - 1.Lantai dump. - 2. Underrun kanan patah - 3. Chasis dump & kisi2 - 4. Bracket clamp Baterai dan cover Baterai - Mekanikal & K3 - 1. Karet susu - 2. Ban Serep - 3. Pin bushing cylinder hoise atas & bawah - 4. Ting tong atas - 5. Karet mounting shower per depan - 6. Grease all fitting - 7. Service berkala','269 jam 56 menit',16196,1,0,NULL,'Closed','Normal','Corrective','UNASSESSED',NULL,'Belum ada PIC',NULL,NULL,NULL,'2026-08-04 23:42:24',NULL,NULL,NULL,NULL,NULL,NULL),('WO-26-009','DT-00064',NULL,NULL,NULL,NULL,NULL,'Yard KM 12 Duri','WELDING - 1 